package io.knowledgebrain.content;
import java.util.*;import java.io.IOException;import jakarta.servlet.http.HttpServletRequest;import org.springframework.web.bind.annotation.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.web.server.ResponseStatusException;import io.micrometer.core.instrument.MeterRegistry;import tools.jackson.databind.json.JsonMapper;
@RestController @ConditionalOnProperty(name="brain.content.concepts.enabled",havingValue="true")
final class RecordConceptsController {
 private final RecordConceptStore store;private final SpaceAuthorizationClient authority;private final ConceptAvailabilityClient concepts;private final MeterRegistry metrics;private final String origin;private final JsonMapper json=JsonMapper.builder().enable(tools.jackson.databind.DeserializationFeature.FAIL_ON_TRAILING_TOKENS).enable(tools.jackson.core.StreamReadFeature.STRICT_DUPLICATE_DETECTION).build();
 RecordConceptsController(RecordConceptStore store,SpaceAuthorizationClient authority,ConceptAvailabilityClient concepts,MeterRegistry metrics,@Value("${brain.content.browser-origin}")String origin){this.store=store;this.authority=authority;this.concepts=concepts;this.metrics=metrics;this.origin=origin;}
 static String tag(long version){return "\"rc"+version+"\"";}
 private long expected(HttpServletRequest r){var h=Collections.list(r.getHeaders("If-Match"));if(h.isEmpty())throw new ResponseStatusException(HttpStatus.PRECONDITION_REQUIRED,"If-Match required");if(h.size()!=1||!h.getFirst().matches("\"rc(0|[1-9][0-9]{0,18})\""))throw RecordConceptStore.bad();try{return Long.parseLong(h.getFirst().substring(3,h.getFirst().length()-1));}catch(NumberFormatException e){throw RecordConceptStore.bad();}}
 private String token(HttpServletRequest r){String token=null;if(r.getCookies()!=null)for(var c:r.getCookies())if(c.getName().equals("__Host-brain_guest")){if(token!=null)throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Ambiguous session");token=c.getValue();}return token;}
 private UUID authorize(UUID space,RecordConceptStore.Kind kind,HttpServletRequest r,boolean write,String parent){if(!r.isSecure())throw RecordConceptStore.bad();if(write&&(Collections.list(r.getHeaders("Origin")).size()!=1||!origin.equals(r.getHeader("Origin"))||r.getHeader("Sec-Fetch-Site")!=null&&!r.getHeader("Sec-Fetch-Site").equals("same-origin")))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Same-origin request required");var token=token(r);return switch(kind){case BOOKMARK->authority.authorizeBookmark(space,token,write,parent);case QUESTION->authority.authorizeQuestion(space,token,write,parent);case DECISION->authority.authorizeDecision(space,token,write,parent);};}
 private void parameters(HttpServletRequest r,Set<String> allowed)throws IOException{for(var p:r.getParameterMap().entrySet())if(!allowed.contains(p.getKey())||p.getValue().length!=1)throw RecordConceptStore.bad();if(r.getMethod().equals("GET")&&r.getInputStream().read()!=-1)throw RecordConceptStore.bad();}
 private long number(String raw,long fallback,long max){if(raw==null)return fallback;if(!raw.matches("[1-9][0-9]{0,18}"))throw RecordConceptStore.bad();try{var n=Long.parseLong(raw);if(n>max)throw RecordConceptStore.bad();return n;}catch(NumberFormatException e){throw RecordConceptStore.bad();}}
 private List<UUID> body(HttpServletRequest r)throws IOException{if(!MediaType.APPLICATION_JSON_VALUE.equalsIgnoreCase(Optional.ofNullable(r.getContentType()).orElse("").split(";",2)[0].strip()))throw new ResponseStatusException(HttpStatus.UNSUPPORTED_MEDIA_TYPE,"JSON required");var bytes=r.getInputStream().readNBytes(2049);if(bytes.length>2048)throw new ResponseStatusException(HttpStatus.PAYLOAD_TOO_LARGE,"Record concept input exceeds 2 KiB");try{var v=json.readTree(bytes);if(v==null||!v.isObject()||v.size()!=1||!v.path("conceptIds").isArray()||v.path("conceptIds").size()>20)throw RecordConceptStore.bad();var result=new ArrayList<UUID>();for(var item:v.path("conceptIds")){if(!item.isString())throw RecordConceptStore.bad();result.add(RecordConceptStore.id(item.asString()));}RecordConceptStore.input(result);return List.copyOf(result);}catch(RuntimeException e){throw RecordConceptStore.bad();}}
 private ResponseEntity<RecordConceptStore.View> response(RecordConceptStore.View v){return ResponseEntity.ok().eTag(tag(v.links().version())).cacheControl(CacheControl.noStore()).body(v);}
 @GetMapping("/api/spaces/{spaceId}/record-concepts/{recordType}/{recordId}") ResponseEntity<RecordConceptStore.View> get(@PathVariable String spaceId,@PathVariable String recordType,@PathVariable String recordId,HttpServletRequest r)throws IOException{parameters(r,Set.of());var space=RecordConceptStore.id(spaceId);var kind=RecordConceptStore.Kind.parse(recordType);var id=RecordConceptStore.id(recordId);authorize(space,kind,r,false,BookmarkController.parent(r));metrics.counter("brain.content.record_concepts.reads","type","current").increment();return response(store.get(space,kind,id));}
 @PutMapping("/api/spaces/{spaceId}/record-concepts/{recordType}/{recordId}") ResponseEntity<RecordConceptStore.View> replace(@PathVariable String spaceId,@PathVariable String recordType,@PathVariable String recordId,HttpServletRequest r)throws IOException{parameters(r,Set.of());var space=RecordConceptStore.id(spaceId);var kind=RecordConceptStore.Kind.parse(recordType);var id=RecordConceptStore.id(recordId);var parent=BookmarkController.parent(r);var actor=authorize(space,kind,r,true,parent);long version=expected(r);var requested=body(r);var current=store.get(space,kind,id);if(current.links().version()!=version)throw new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,"Record concept links changed; inspect latest");if(!current.recordState().equals("ACTIVE"))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Archived record cannot change links");var added=requested.stream().filter(v->current.links().items().stream().noneMatch(item->item.conceptId().equals(v))).toList();if(!added.isEmpty())concepts.check(space,added,token(r),parent);var value=store.replace(space,kind,id,actor,version,requested,parent.substring(3,35));metrics.counter("brain.content.record_concepts.changes").increment();return response(value);}
 @GetMapping("/api/spaces/{spaceId}/record-concepts/{recordType}/{recordId}/revisions") ResponseEntity<List<RecordConceptStore.Revision>> history(@PathVariable String spaceId,@PathVariable String recordType,@PathVariable String recordId,HttpServletRequest r)throws IOException{parameters(r,Set.of("before","limit"));var space=RecordConceptStore.id(spaceId);var kind=RecordConceptStore.Kind.parse(recordType);var id=RecordConceptStore.id(recordId);authorize(space,kind,r,false,BookmarkController.parent(r));long before=number(r.getParameter("before"),Long.MAX_VALUE,Long.MAX_VALUE);int limit=(int)number(r.getParameter("limit"),5,10);metrics.counter("brain.content.record_concepts.reads","type","history").increment();return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(store.history(space,kind,id,before,limit));}
 @GetMapping("/api/spaces/{spaceId}/concept-references/{conceptId}/records") ResponseEntity<RecordConceptStore.Page> references(@PathVariable String spaceId,@PathVariable String conceptId,HttpServletRequest r)throws IOException{parameters(r,Set.of("type","state","after","limit"));var space=RecordConceptStore.id(spaceId);var concept=RecordConceptStore.id(conceptId);var kind=RecordConceptStore.Kind.parse(Optional.ofNullable(r.getParameter("type")).orElse("BOOKMARK"));authorize(space,kind,r,false,BookmarkController.parent(r));metrics.counter("brain.content.record_concepts.reads","type","references").increment();return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(store.references(space,concept,kind,Optional.ofNullable(r.getParameter("state")).orElse("ACTIVE"),r.getParameter("after"),(int)number(r.getParameter("limit"),20,100)));}
}
